#!/usr/bin/env node
/**
 * Scans packages/tools/src/tools/<slug>/ and writes two generated files:
 *   registry.generated.ts  metadata for every tool (safe to import on the server)
 *   loaders.generated.ts   lazy loaders for each tool's UI (client only)
 *
 * Run automatically before `dev` and `build`. Also run by the test suite to make sure the files are current.
 */
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const toolsDir = join(root, "packages", "tools", "src", "tools");

export function scanTools() {
  return readdirSync(toolsDir)
    .filter((name) => statSync(join(toolsDir, name)).isDirectory())
    .sort()
    .map((slug) => {
      const hasMeta = existsSync(join(toolsDir, slug, "meta.ts"));
      const hasTool = existsSync(join(toolsDir, slug, "Tool.tsx"));
      if (!hasMeta || !hasTool) {
        throw new Error(`tools/${slug} must contain both meta.ts and Tool.tsx (found: ${hasMeta ? "meta.ts" : ""} ${hasTool ? "Tool.tsx" : ""})`);
      }
      return slug;
    });
}

const ident = (slug) => `meta_${slug.replace(/[^a-z0-9]/g, "_")}`;

export function render(slugs) {
  const header = "// AUTO-GENERATED by scripts/gen-registry.mjs. Do not edit by hand.\n";
  const registry =
    header +
    `import type { ToolMeta } from "./define";\n` +
    slugs.map((s) => `import ${ident(s)} from "./tools/${s}/meta";`).join("\n") +
    `\n\nexport const tools: readonly ToolMeta[] = [\n${slugs.map((s) => `  ${ident(s)},`).join("\n")}\n];\n`;
  const loaders =
    header +
    `import type { ComponentType } from "react";\n\n` +
    `export type ToolLoader = () => Promise<{ default: ComponentType }>;\n\n` +
    `export const toolLoaders: Record<string, ToolLoader> = {\n${slugs.map((s) => `  "${s}": () => import("./tools/${s}/Tool"),`).join("\n")}\n};\n`;
  return { registry, loaders };
}

export function generate({ check = false } = {}) {
  const slugs = scanTools();
  const { registry, loaders } = render(slugs);
  const targets = [
    [join(root, "packages", "tools", "src", "registry.generated.ts"), registry],
    [join(root, "packages", "tools", "src", "loaders.generated.ts"), loaders],
  ];
  let stale = false;
  for (const [file, content] of targets) {
    const current = existsSync(file) ? readFileSync(file, "utf8") : "";
    if (current !== content) {
      stale = true;
      if (!check) writeFileSync(file, content);
    }
  }
  return { slugs, stale };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const { slugs, stale } = generate({ check: process.argv.includes("--check") });
  if (process.argv.includes("--check")) {
    if (stale) {
      console.error("Generated registry is out of date. Run `node scripts/gen-registry.mjs`.");
      process.exit(1);
    }
  } else {
    console.log(`Registry: ${slugs.length} tools${stale ? " (updated)" : ""}`);
  }
}
